(7550554, 1209817, 141319, '<td valign="top">BRILLIANT!</td>', 'BRILLIANT!', '2018-01-01 02:07:33.000000', NULL, 1),
(7550555, 1209702, 141319, '<td valign="top">The colors are wonderful here! Nice interpretation of the theme too.</td>', 'The colors are wonderful here! Nice interpretation of the theme too.', '2018-01-01 02:08:48.000000', NULL, 1),
