(7550847, 1209832, 159132, '<td valign="top">This is a beautiful treatment of plastic. Photography is all about light, and you have turned what is probably a $19.95 set of poolside safe wine glasses into a piece of art. Well done.</td>', 'This is a beautiful treatment of plastic. Photography is all about light, and you have turned what is probably a $19.95 set of poolside safe wine glasses into a piece of art. Well done.', '2018-01-02 22:37:41.000000', NULL, 1),
(7550848, 1209625, 159132, '<td valign="top">Nicely done. I purchased a backlit photograph earlier this year as I like this treatment. Plus it is on a micro-scale. 8</td>', 'Nicely done. I purchased a backlit photograph earlier this year as I like this treatment. Plus it is on a micro-scale. 8', '2018-01-02 22:38:41.000000', NULL, 1),
(7550849, 1209561, 159132, '<td valign="top">Excellent. Plus I love the macro/micro treatment. Even has a sensuous quality, with the curves around the edges.</td>', 'Excellent. Plus I love the macro/micro treatment. Even has a sensuous quality, with the curves around the edges.', '2018-01-02 22:39:42.000000', NULL, 1),
(7550850, 1209833, 159132, '<td valign="top">This is excellent. A great twist on the documentary issue yet the beauty of the light catches the eye enough to catch the attention. Well done</td>', 'This is excellent. A great twist on the documentary issue yet the beauty of the light catches the eye enough to catch the attention. Well done', '2018-01-02 22:40:39.000000', NULL, 1),
(7550851, 1209815, 159132, '<td valign="top">Excellent. Would have gone higher except for the subject which is well trodden</td>', 'Excellent. Would have gone higher except for the subject which is well trodden', '2018-01-02 22:41:16.000000', NULL, 1),
(7550853, 1209840, 159132, '<td valign="top">Nice treatment of an obvious subject. Especially like the numerous individual glints</td>', 'Nice treatment of an obvious subject. Especially like the numerous individual glints', '2018-01-02 22:42:07.000000', NULL, 1),
(7550854, 1209723, 159132, '<td valign="top">Original composition yet a bit too creepy. Wish the subject had had more freedom</td>', 'Original composition yet a bit too creepy. Wish the subject had had more freedom', '2018-01-02 22:43:01.000000', NULL, 1),
(7550855, 1209690, 159132, '<td valign="top">Excellent mixture of the documentary issue juxtaposed with some natural beauty</td>', 'Excellent mixture of the documentary issue juxtaposed with some natural beauty', '2018-01-02 22:43:42.000000', NULL, 1),
(7550856, 1209848, 159132, '<td valign="top">Nice. I think the subject would have called for a bit more DOF</td>', 'Nice. I think the subject would have called for a bit more DOF', '2018-01-02 22:44:08.000000', NULL, 1),
(7550857, 1209820, 159132, '<td valign="top">Plastic at its most beautiful. Excellent capture of light.</td>', 'Plastic at its most beautiful. Excellent capture of light.', '2018-01-02 22:44:57.000000', NULL, 1),
(7550858, 1209843, 159132, '<td valign="top">OMG. Thanks for pointing out that plastic is a wonderful boon to society</td>', 'OMG. Thanks for pointing out that plastic is a wonderful boon to society', '2018-01-02 22:45:26.000000', NULL, 1),
