(7551425, 1209745, 68504, '<td valign="top">this is most arresting. it is the man, of course, but he is set up by the blue orange palette, and the impeccable composition. and there he is, his pale pate nearly blasted by overexposure. or maybe just 30%. His purpose in the tableau is to hold that plastic bag. for whatever it is worth.</td>', 'this is most arresting. it is the man, of course, but he is set up by the blue orange palette, and the impeccable composition. and there he is, his pale pate nearly blasted by overexposure. or maybe just 30%. His purpose in the tableau is to hold that plastic bag. for whatever it is worth.', '2018-01-07 19:33:05.000000', NULL, 1),
(7551442, 1209570, 94815, '<td valign="top">Poor thing.I can almost feel sympathetic. Neatly twisted.</td>', 'Poor thing.I can almost feel sympathetic. Neatly twisted.', '2018-01-07 21:07:51.000000', NULL, 1),
(7551443, 1209788, 94815, '<td valign="top">Love the foreboding noirish shadows. Good irony.</td>', 'Love the foreboding noirish shadows. Good irony.', '2018-01-07 21:13:24.000000', NULL, 1),
(7551444, 1209814, 94815, '<td valign="top">Appropriately freakish.</td>', 'Appropriately freakish.', '2018-01-07 21:14:17.000000', NULL, 1),
(7551446, 1209820, 94815, '<td valign="top">Nicely constructed. Good tones. Totally conceals its plastic content in plain sight.</td>', 'Nicely constructed. Good tones. Totally conceals its plastic content in plain sight.', '2018-01-07 21:18:09.000000', NULL, 1),
(7551447, 1209737, 94815, '<td valign="top">Makes its point. Good POV.</td>', 'Makes its point. Good POV.', '2018-01-07 21:18:35.000000', NULL, 1),
(7551448, 1209690, 94815, '<td valign="top">Ooh. So arty</td>', 'Ooh. So arty', '2018-01-07 21:20:41.000000', NULL, 1),
(7551449, 1209803, 94815, '<td valign="top">Normally don''t like partial desats, but this works very well to make the point. very eye-catching, even scintillating processing.</td>', 'Normally don''t like partial desats, but this works very well to make the point. very eye-catching, even scintillating processing.', '2018-01-07 21:25:13.000000', NULL, 1),
